import{_ as i,C as t,c as s,o as r,aj as p,G as o,w as l}from"./chunks/framework.Bfdr4H5E.js";const g=JSON.parse('{"title":"For Those Concerned That It Appears Too Simple","description":"","frontmatter":{"outline":"deep","prev":{"text":"10 Most Common Trading Mistakes You Should Avoid","link":"/trading-with-pav/10-most-common-trading-mistakes-you-should-avoid"},"next":{"text":"For Those Who Perceive It As Too Complex","link":"/trading-with-pav/for-those-who-perceive-it-as-too-complex"}},"headers":[],"relativePath":"trading-with-pav/for-those-concerned-that-it-appears-too-simple.md","filePath":"trading-with-pav/for-those-concerned-that-it-appears-too-simple.md"}'),h={name:"trading-with-pav/for-those-concerned-that-it-appears-too-simple.md"};function d(c,e,m,u,f,w){const a=t("GraphComment"),n=t("ClientOnly");return r(),s("div",null,[e[0]||(e[0]=p('<h1 id="for-those-concerned-that-it-appears-too-simple" tabindex="-1">For Those Concerned That It Appears Too Simple <a class="header-anchor" href="#for-those-concerned-that-it-appears-too-simple" aria-label="Permalink to &quot;For Those Concerned That It Appears Too Simple&quot;">​</a></h1><p>This article is For Those Concerned That It Appears Too Simple.</p><p>Trade weakness when price interacts with S/R. Trade weakness in pullbacks within a trend.</p><p>Can it really be that simple?</p><p>The fact is that while these concepts are simple to define, they’re not simple to trade. That’s why we have the trader development in Module 7. It’s a process of growth &amp; development.</p><div class="warning custom-block"><p class="custom-block-title">It&#39;s all about</p><ul><li>It’s about learning to deal with the uncertainty at the right hand edge of the chart, and being ok with that feeling of insecurity and doubt.</li><li>It’s about having confidence to get into a trade, despite the uncertainty that you WILL feel, because you know that whatever happens you have the skills and experience to appropriately manage the trade.</li><li>The skills and experience to deal with those that don’t work, in such a way as to minimize damage to both your account and your psychological capital.</li><li>And the skills and experience to manage the winning trades, in order to squeeze as much reward as possible out of the market.</li></ul></div><p>Yes, the strategy is simple to define. Considerable complexity could have been added. I could have added names for numerous patterns of price action, and classification of trend type or market environment.</p><p>I could have labeled dozens of different types of S/R. I don’t believe it’s necessary though.</p><p>Your mind will add complexity to the process of trading. It’s best to keep the strategy itself as simple as possible.</p><p>So yes its simple but achieving growth &amp; development is complex process with long journey ahead.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',11)),o(n,null,{default:l(()=>[o(a)]),_:1})])}const v=i(h,[["render",d]]);export{g as __pageData,v as default};
